\end{itemize}
\section*{Projects}
\noindent\textbf{Ariadne: On-Call Agent with Graph Memory}\hfill Oct 2026\\
\textit{Graph Hacks (FalkorDB) | Personal Project}
\begin{itemize}
\item \textbf{Agent Design:} Built an on-call agent over a FalkorDB graph with nine graph tools; Cypher and graph algorithms rank the suspect commit while the LLM only chooses tools and explains, so the verdict is unchanged without the model.
\item \textbf{Measured Memory:} Resolved incidents are written back as reusable plans; across 20 alerts per arm the warm path took four tool calls and reached the same culprit as cold on all 20. Shipped an MCP server, Alertmanager webhook, hosted demo and 168 tests.
\end{itemize}
\noindent\textbf{AgriN: Digital Agriculture Advisory Network}\hfill 2026\\
\textit{Personal Project}
\begin{itemize}
\item \textbf{Deterministic Engine:} FAO-56 evapotranspiration, soil and paddy water balance, nutrients and crop rotation are computed by code; the LLM only narrates, and a guard rejects any figure that is not in the engine output.
\item \textbf{Pipeline and ML:} Ingests weather, soil and Sentinel satellite data on a schedule; shipped an on-device rice disease model (10 classes, 0.981 accuracy on answered photos) with cloud fallback, spend caps and an offline-first mobile app.
\end{itemize}
\noindent\textbf{Jal Panchayat: Village Water Safety Verdicts}\hfill 2026\\
\textit{Code for a Billion | Personal Project}
\begin{itemize}
\item \textbf{Fail-Closed Engine:} Deterministic IS 10500 verdict engine over 16 water-quality parameters that reports untested water as unknown, never safe; 19 property tests.
\item \textbf{Safe Narration:} Narration guard blocks invented figures and the boiling myth; reply rendering runs with no model. Public data shows 72,606 contaminated samples with remedial action recorded for 31\%.
\end{itemize}
\noindent\textbf{RoadLedger: Road Defect Measurement}\hfill 2026\\
\textit{OpenCV AI Competition 2026 | Personal Project}
\begin{itemize}
\item \textbf{Measured Evidence:} OpenCV pipeline that rectifies the road plane and measures each defect's area in square metres, scores agreement across views and asks a person when they disagree; 41 invariant tests.
\item \textbf{Live Capture:} Phone-mounted capture mode and a review UI deployed on AWS CloudFront, producing prioritised, costed repair work orders.
\end{itemize}
